// C++14 allows more complex constexpr functions
class Point {
public:
  constexpr Point(double x = 0, double y = 0) noexcept : x_(x), y_(y) {}
  constexpr double x() const noexcept { return x_; }
  constexpr double y() const noexcept { return y_; }

  // C++14 allows void return and mutation
  constexpr void setX(double newX) noexcept { x_ = newX; }
  constexpr void setY(double newY) noexcept { y_ = newY; }
private:
  double x_, y_;
};

// C++14 allows local variables and multiple statements
constexpr Point reflect(const Point& p) noexcept
{
  Point result;                  // Create a local, non-const object
  result.setX(-p.x());         // Call C++14 constexpr mutators
  result.setY(-p.y());
  return result;                 // Return a copy of the modified object
}

constexpr Point p1(10, 20);
constexpr Point p2 = reflect(p1); // p2's value (-10, -20) is known at compile time
